#!/usr/bin/env python3
"""Robust one-pass JSONL sessionization with a corruption quarantine.

Reads an events JSONL file once (binary mode), classifying each line:
  - good lines are sessionized per user with a 30-minute inactivity gap;
  - bad lines are routed to a quarantine JSONL as
        {"line_no": <int>, "raw": <utf-8 w/ replacement chars>, "reason": <str>}
    where reason is one of PARSE_ERROR, MISSING_FIELD, BAD_TIMESTAMP.

Guarantee: the session output produced from a corrupted file is byte-identical
to the session output produced from the pre-cleaned file containing only the
good lines of that same file.
"""

from __future__ import annotations

import argparse
import json
import sys
from datetime import datetime, timedelta
from typing import Iterator

REQUIRED_FIELDS = ("event_id", "user_id", "event_type", "ts")
GAP = timedelta(minutes=30)
QUARANTINE_REASONS = ("PARSE_ERROR", "MISSING_FIELD", "BAD_TIMESTAMP")

_TS_FALLBACK_FORMATS = (
    "%Y-%m-%dT%H:%M:%S",
    "%Y-%m-%d %H:%M:%S",
    "%Y/%m/%d %H:%M:%S",
    "%Y%m%dT%H%M%S",
)


def parse_ts(raw: str) -> datetime:
    """Parse a timestamp or raise ValueError."""
    try:
        return datetime.fromisoformat(raw)
    except (TypeError, ValueError):
        pass
    for fmt in _TS_FALLBACK_FORMATS:
        try:
            return datetime.strptime(raw, fmt)
        except (TypeError, ValueError):
            continue
    raise ValueError(f"unparseable timestamp: {raw!r}")


def classify(text: str) -> tuple[str | None, dict | None]:
    """Classify one decoded line.

    Returns ("ok", event) for good lines, else (<reason>, None).
    """
    try:
        obj = json.loads(text)
    except (json.JSONDecodeError, ValueError):
        return "PARSE_ERROR", None

    if not isinstance(obj, dict) or any(f not in obj for f in REQUIRED_FIELDS):
        return "MISSING_FIELD", None

    try:
        obj["ts"] = parse_ts(obj["ts"])
    except ValueError:
        return "BAD_TIMESTAMP", None

    return "ok", obj


def iter_lines(path: str) -> Iterator[tuple[int, str]]:
    """Yield (line_no, decoded_text) in one pass; invalid UTF-8 becomes U+FFFD."""
    with open(path, "rb") as f:
        for line_no, raw_bytes in enumerate(f, 1):
            yield line_no, raw_bytes.decode("utf-8", errors="replace").rstrip("\r\n")


def sessionize(events: list[dict]) -> list[list[dict]]:
    """Split per-user event streams into sessions on a >30 min gap.

    Events are ordered by (user_id, ts); sessions are lists of raw event dicts.
    """
    by_user: dict[str, list[dict]] = {}
    for ev in events:
        by_user.setdefault(ev["user_id"], []).append(ev)

    sessions: list[list[dict]] = []
    for user in sorted(by_user):
        stream = sorted(by_user[user], key=lambda e: e["ts"])
        current: list[dict] = [stream[0]]
        for ev in stream[1:]:
            if ev["ts"] - current[-1]["ts"] <= GAP:
                current.append(ev)
            else:
                sessions.append(current)
                current = [ev]
        sessions.append(current)

    # Deterministic global ordering: by session start time.
    sessions.sort(key=lambda s: s[0]["ts"])
    return sessions


def process(input_path: str,
            session_path: str,
            quarantine_path: str | None = None) -> list[list[dict]]:
    """One pass over input_path. Writes session + quarantine outputs."""
    events: list[dict] = []
    quarantine_lines: list[str] = []

    for line_no, text in iter_lines(input_path):
        verdict, obj = classify(text)
        if verdict == "ok":
            events.append(obj)
        elif quarantine_path is not None:
            entry = {"line_no": line_no, "raw": text, "reason": verdict}
            quarantine_lines.append(
                json.dumps(entry, ensure_ascii=False, sort_keys=True) + "\n"
            )

    if quarantine_path is not None:
        with open(quarantine_path, "w", encoding="utf-8") as qf:
            qf.writelines(quarantine_lines)

    sessions = sessionize(events)

    def render(sess: list[dict]) -> str:
        return json.dumps(
            {
                "user_id": sess[0]["user_id"],
                "start": sess[0]["ts"].isoformat(),
                "end": sess[-1]["ts"].isoformat(),
                "events": [
                    {**{k: v for k, v in ev.items() if k != "ts"},
                     "ts": ev["ts"].isoformat()}
                    for ev in sess
                ],
            },
            ensure_ascii=False,
            sort_keys=True,
        ) + "\n"

    with open(session_path, "w", encoding="utf-8", newline="\n") as sf:
        sf.writelines(render(s) for s in sessions)

    return sessions


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("input")
    ap.add_argument("--sessions", default="sessions.jsonl")
    ap.add_argument("--quarantine", default="quarantine.jsonl")
    args = ap.parse_args(argv)

    sessions = process(args.input, args.sessions, args.quarantine)
    print(
        f"{args.input}: {len(sessions)} sessions -> {args.sessions}; "
        f"quarantine -> {args.quarantine}",
        file=sys.stderr,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

